def parallel_svg():
    W,H=1000,470; x0,x1=200,930
    s=[f'<figure class="paral glass reveal"><svg viewBox="0 0 {W} {H}" role="img" aria-label="渐进平行结构图">',
       f'<line x1="{x0}" y1="30" x2="{x0}" y2="{H-40}" stroke="#f5b942" stroke-width="3" stroke-dasharray="6 6"/><line x1="{x1}" y1="30" x2="{x1}" y2="{H-40}" stroke="#3fd39a" stroke-width="3" stroke-dasharray="6 6"/>',
       f'<text x="{x0}" y="{H-12}" text-anchor="middle" font-size="18" fill="#f5b942">✝️ 第一次降临·升天</text><text x="{x1-10}" y="{H-12}" text-anchor="end" font-size="18" fill="#3fd39a">再来·审判 👑</text>']
    for i,(sec,cs) in enumerate(SECS):
        y=60+i*54; xs=x0 if i!=3 else x0-55; w=(x1-xs)
        s.append(f'<g class="pbar" style="--d:{i*0.25}s"><text x="8" y="{y+6}" font-size="17" fill="currentColor">{sec["ic"]} {sec["n"]}</text>'
                 f'<rect x="{xs}" y="{y-14}" width="{w}" height="26" rx="13" fill="{sec["col"]}" opacity="{0.35+i*0.08:.2f}"/>'
                 f'<text x="{xs+14}" y="{y+5}" font-size="15" fill="#fff" font-weight="700">启 {sec["r"]}：{sec["t"]}</text>'
                 f'<circle cx="{x1}" cy="{y-1}" r="9" fill="#fff" stroke="{sec["col"]}" stroke-width="4"/></g>')
    s.append('</svg><figcaption>七段异象像七次「重播」，每段都覆盖从基督第一次降临到再来的整个时期，并都以末日审判或得胜收尾；后面的段落越来越深入、越来越接近终局（渐进）。第4段（12章）从基督降生（甚至更早的属灵争战）讲起，所以起点更早。（依 Hendriksen《得胜有余》的七段划分）</figcaption></figure>')
    return "".join(s)
