    b.append('<h2 id="t1">一、作者自己给的大纲：启1:19</h2>'+verse_card("启1:19")+tbl(["","经文","内容"],[("「所看见的」","第1章","人子在灯台中间的异象"),("「现在的事」","第2–3章","七个教会的现况"),("「将来必成的事」","第4–22章","从天上的视角看整个教会时代直到终局")])+'<p class="note">注意：「将来」是从约翰的时代说的，并不等于「我们这个时代之后才开始」。4:1「以后必成的事」引用但2:28-29，意思是「末后的日子」已经开始。</p>')
