    b.append('<h2 id="t7">七、解经八原则</h2><ol class="principles">'+"".join(f'<li class="reveal">{md(x)}</li>' for x in ["**以经解经**：先问旧约怎么用这个象征（BC 7：圣经是完全的准则）。","**听见 vs 看见**：约翰「听见」狮子，「看见」羔羊（5:5-6）；「听见」十四万四千，「看见」无数的人（7:4,9）——同一实体的两个面向。","**象征优先**：书一开始就说是「指示」（1:1，原文 *esēmanen* 与「记号」同字根）。","**原读者能懂**：任何解释都必须对第一世纪七教会有意义。","**结构决定次序**：平行而非直线。","**基督中心**：每一段都回到宝座与羔羊。","**不猜日期**：「那日子、那时辰无人知道」（BC 37）。","**在敬拜中读**：「念这书上预言的和那些听见又遵守其中所记载的，都是有福的」（1:3）。"])+'</ol>')
    b.append('<h2 id="t8">八、七福与九首天上颂歌</h2>'+tbl(["经文","有福的人"],BEAT)+tbl(["经文","歌者","内容"],HYM))
    b.append('<h3 id="t8b">⚠️ 历史一瞥：教皇是敌基督吗？</h3><p>'+md("宗教改革时期的信条常把「敌基督」与罗马教皇的职分联系起来，例如威斯敏斯特信仰告白原版第25章第6节（1903 年美国长老会修订时删去此句）：")+'</p>'+wq('wcf',25,6)+'<p class="note">'+md("三项联合信条没有这样的条文。改革宗解经家（如 Hendriksen）通常把「兽」理解为历代逼迫教会的政权与假宗教，末了有极致的显现（{{帖后2:3-4}}），而不把某一个职位等同于启示录的兽。")+'</p>')
    return "".join(b)
