def church_cards():
    b=[]
    for c in CH:
        b.append(f'''<article class="church glass reveal" id="c-{c["k"]}" style="--gc:{c["col"]}"><header><span class="ci">{c["ic"]}</span><h3 id="cc-{c["k"]}">{c["n"]} <small>{c["en"]} · {esc(c["ref"])}</small></h3></header>
<div class="cgrid"><div class="cmap">{geo.mini(c["k"])}<small>📍 今：{esc(c["today"])}</small></div><div class="cbg"><h4>🏛️ 城市背景</h4><p>{md(c["bg"])}</p></div></div>
<div class="letter7"><div class="l7 t"><b>👤 基督的自称</b><span>{esc(c["title"])}</span></div><div class="l7 p"><b>👍 称赞</b><span>{esc(c["praise"])}</span></div><div class="l7 r"><b>⚠️ 责备</b><span>{esc(c["rebuke"])}</span></div><div class="l7 e"><b>📣 劝勉</b><span>{esc(c["ex"])}</span></div><div class="l7 w"><b>🏆 应许</b><span>{esc(c["promise"])}</span></div></div>
{verse_card(c["kv"])}<p class="capp">🌱 {md(c["app"])}</p></article>''')
