def churches_intro():
    b=['<h2 id="cv">🕯️ 七教会总览</h2>']
    b.append('<h3 id="cv1">✉️ 七封书信的七重格式</h3>'+flow(["**收信人**：「写信给……教会的使者」","**基督的自称**：取自第1章的异象","**「我知道你的行为」**：称赞","**责备**：「然而有一件事我要责备你」","**劝勉/警告**：悔改、持守","**「圣灵向众教会所说的话，凡有耳的就应当听」**"],"**给得胜者的应许**：都在 21–22 章实现"))
    b.append('<h3 id="cv2">📊 七教会对照表</h3>'+tbl(["教会","称赞","责备","应许（在新天新地实现）"],[(f'<a href="#c-{c["k"]}">{c["ic"]} {c["n"]}</a>',c["praise"],c["rebuke"],c["promise"]) for c in CH],"cmpch"))
    b.append('<div class="two"><div class="card glass"><h4>🔄 交错结构（A-B-C-B-A）</h4><p>'+md("**以弗所**（有危险：失去灯台） · **士每拿**（无责备） · **别迦摩、推雅推喇、撒狄**（混合：有好有坏） · **非拉铁非**（无责备） · **老底嘉**（几乎全是责备）。中间三封的问题最复杂——妥协。")+'</p></div><div class="card glass"><h4>🔁 应许的实现</h4><p>'+md("生命树（2:7 → 22:2）；第二次死（2:11 → 20:14）；新名（2:17 → 22:4）；晨星（2:28 → 22:16）；生命册（3:5 → 21:27）；新耶路撒冷（3:12 → 21:2）；宝座（3:21 → 22:3-5）。")+'</p></div></div>')
    return "".join(b)
